const NL=String.fromCharCode(10);
function unwrap(v){ if(typeof v==='object'&&v!==null){ if(v.start)return v.start; if(v.name)return v.name; if(Array.isArray(v))return v.map(x=>(x&&(x.plain_text||x.name))||'').join(', '); return ''; } return v; }
function flatKey(k){ return 'property_'+k.toString().toLowerCase().replace(/[^a-z0-9äöüß]+/g,'_'); }
function getVal(o,k){ if(o[k]!==undefined&&o[k]!==null) return unwrap(o[k]); const fk=flatKey(k); if(o[fk]!==undefined&&o[fk]!==null) return unwrap(o[fk]); const props=o.properties||{}; const p=props[k]; if(!p)return undefined; if(p.type==='title')return (p.title||[]).map(t=>t.plain_text).join(''); if(p.type==='rich_text')return (p.rich_text||[]).map(t=>t.plain_text).join(''); if(p.type==='select')return p.select?p.select.name:''; if(p.type==='status')return p.status?p.status.name:''; if(p.type==='checkbox')return p.checkbox; if(p.type==='date')return p.date?p.date.start:''; if(p.type==='email')return p.email; return undefined; }
const norm=(s)=>(s||'').toString().trim().toLowerCase().replace(/\s+/g,' ');
const roster=[]; const ignoreNames=[];
for(const it of $('Teilnehmer-Liste lesen').all()){ const o=it.json; const name=(getVal(o,'Name')||'').toString().trim(); if(!name)continue; const rolle=(getVal(o,'Rolle')||'').toString(); const aktiv=getVal(o,'Aktiv'); const sollRaw=(getVal(o,'Soll-Zeit')||'').toString(); const soll=sollRaw.indexOf('15')>=0?'9-15':'9-12'; const aliasRaw=(getVal(o,'Zoom-Anzeigename')||'').toString(); const aliases=[name].concat(aliasRaw.split(',')).map(s=>s.trim()).filter(Boolean); const abRaw=getVal(o,'Dabei ab'); const ab=abRaw?abRaw.toString().slice(0,10):''; const isAktiv=(aktiv===true||aktiv==='true'||aktiv==='__YES__'); if(rolle==='Teilnehmer'&&isAktiv){ roster.push({name,soll,aliases,ab}); } else { for(const a of aliases) ignoreNames.push(a); } }
if(roster.length===0){ throw new Error('Doppel-Schutz: Die Teilnehmerliste aus Notion konnte nicht gelesen werden (Roster leer). Es wurde NICHTS ins Klassenbuch geschrieben. Bitte die Notion-Verbindung und die Feldnamen der Teilnehmer-Datenbank pruefen.'); }
const extraIgnore=['timo-merz@web.de','iphone von timo','timo merz','meral celik'];
const aliasMap={}; for(const p of roster) for(const a of p.aliases) aliasMap[norm(a)]=p;
const ignoreSet=new Set(ignoreNames.concat(extraIgnore).map(norm));
const sollWindow={'9-12':[9,12],'9-15':[9,15]};
const pageByDate={}; for(const it of $('Klassenbuch lesen').all()){ const o=it.json; let dv=getVal(o,'Datum'); if(dv){ dv=dv.toString().slice(0,10); let pid=o.id||''; if(!pid&&o.url){ const parts=o.url.split('-'); pid=parts[parts.length-1]; } if(pid) pageByDate[dv]=pid; } }
const rows=[]; for(const item of $('Teilnehmer je Meeting').all()){ const parts=(item.json&&item.json.participants)||[]; for(const p of parts){ if(!p.join_time)continue; rows.push({name:p.name||'',join:new Date(p.join_time),leave:p.leave_time?new Date(p.leave_time):new Date(p.join_time)}); } }
const berlinDate=(d)=>DateTime.fromJSDate(d).setZone('Europe/Berlin').toFormat('yyyy-MM-dd');
const fmtBerlin=(ms)=>DateTime.fromMillis(ms).setZone('Europe/Berlin').toFormat('HH:mm');
const wochentage=['So','Mo','Di','Mi','Do','Fr','Sa'];
function isoWeek(dstr){ const d=new Date(dstr+'T00:00:00Z'); const day=(d.getUTCDay()+6)%7; d.setUTCDate(d.getUTCDate()-day+3); const ft=new Date(Date.UTC(d.getUTCFullYear(),0,4)); const fd=(ft.getUTCDay()+6)%7; ft.setUTCDate(ft.getUTCDate()-fd+3); return 1+Math.round((d.getTime()-ft.getTime())/(7*86400000)); }
const meetingEnd={}; for(const r of rows){ const dt=berlinDate(r.join); const lv=r.leave.getTime(); if(!(dt in meetingEnd)||lv>meetingEnd[dt]) meetingEnd[dt]=lv; }
const byDate={}; for(const r of rows){ const nn=norm(r.name); if(ignoreSet.has(nn))continue; const date=berlinDate(r.join); byDate[date]=byDate[date]||{persons:{},unknown:{}}; const person=aliasMap[nn]; if(person){ byDate[date].persons[person.name]=byDate[date].persons[person.name]||{person,sessions:[]}; byDate[date].persons[person.name].sessions.push([r.join,r.leave]); } else { byDate[date].unknown[r.name]=(byDate[date].unknown[r.name]||0)+1; } }
function minutesIn(sessions,ws,we){ let ivs=sessions.map(([s,e])=>[Math.max(s.getTime(),ws),Math.min(e.getTime(),we)]).filter(([s,e])=>e>s); ivs.sort((a,b)=>a[0]-b[0]); let total=0,cs=null,ce=null; for(const [s,e] of ivs){ if(cs===null){cs=s;ce=e;} else if(s<=ce){ce=Math.max(ce,e);} else {total+=ce-cs;cs=s;ce=e;} } if(cs!==null)total+=ce-cs; return Math.round(total/60000); }
function rawSpan(sessions){ let mn=null,mx=null; for(const [s,e] of sessions){ const st=s.getTime(),et=e.getTime(); if(mn===null||st<mn)mn=st; if(mx===null||et>mx)mx=et; } return [mn,mx]; }
const out=[];
for(const date of Object.keys(byDate).sort()){ const bucket=byDate[date]; const dayStartDT=DateTime.fromISO(date,{zone:'Europe/Berlin'}).startOf('day'); const mEnd=meetingEnd[date]; const anwesende=[]; const present=new Set();
 for(const key in bucket.persons){ const {person,sessions}=bucket.persons[key]; present.add(key); const [wsH,weH]=sollWindow[person.soll]; const ws=dayStartDT.plus({hours:wsH}).toMillis(); const we=dayStartDT.plus({hours:weH}).toMillis(); const effEnd=Math.min(we,mEnd); const erreichbar=Math.max(0,Math.round((effEnd-ws)/60000)); const min=minutesIn(sessions,ws,effEnd); const cov=erreichbar>0?min/erreichbar:0; const sp=rawSpan(sessions); const status=min<=0?'⚠️ Rücksprache':(cov>=0.6?'✅ erfüllt':'⚠️ Rücksprache'); anwesende.push({name:person.name,soll:person.soll+' Uhr',von:fmtBerlin(sp[0]),bis:fmtBerlin(sp[1]),minuten:min,abdeckung:Math.round(cov*100)+'%',status}); }
 anwesende.sort((a,b)=>a.name.localeCompare(b.name));
 const aktivAmTag=roster.filter(p=>!p.ab||date>=p.ab);
 const abwesende=aktivAmTag.filter(p=>!present.has(p.name)).map(p=>p.name);
 const rueck=anwesende.filter(a=>a.status.indexOf('Rücksprache')>=0).map(a=>a.name);
 const unbekannt=Object.keys(bucket.unknown);
 const d=new Date(date+'T12:00:00Z'); const wt=wochentage[d.getUTCDay()];
 const pp=date.split('-'); const dmy=pp[2]+'.'+pp[1]+'.'+pp[0];
 const lines=anwesende.map(a=>a.name+' ('+a.soll+'): '+a.von+'–'+a.bis+' · '+a.minuten+' Min · '+a.abdeckung+' · '+a.status);
 let extra=''; if(unbekannt.length) extra=NL+'⚠️ Unbekannt: '+unbekannt.join(', ');
 const anwesenheit_text='Meeting-Ende: '+fmtBerlin(mEnd)+NL+lines.join(NL)+extra;
 const pid=pageByDate[date]||'';
 out.push({json:{datum:date,wochentag:wt,kurstag:wt+', '+dmy,kw:isoWeek(date),meeting_ende:fmtBerlin(mEnd),anwesend_anzahl:anwesende.length,teilnehmer_gesamt:aktivAmTag.length,abwesend_text:abwesende.length?abwesende.join(', '):'—',ruecksprache_text:rueck.length?rueck.join(', '):'—',anwesenheit_text,unbekannt,existing_page_id:pid,vorhanden:pid?'ja':'nein'}}); }
return out;
